1	import { chmodSync, existsSync, mkdirSync, readFileSync, unlinkSync, writeFileSync } from "node:fs";
2	import { join, resolve } from "node:path";
3	import { createInterface } from "node:readline";
4	import YAML from "yaml";
5	import { detectFormat, fingerprint, listingPayload, signBytes, verifyPack } from "@runlog/rules-schema";
6	import { configDir as sessionConfigDir, deviceFlow, needsRenewal, realDeps, renew, type FlowDeps, type Session } from "@runlog/session";
7	
8	/**
9	 * The command line, as somebody.
10	 *
11	 * `runlog login` signs in the way a terminal can: it asks WorkOS for a short
12	 * code, shows it with a link, and waits while you confirm it in a browser:
13	 * the OAuth device flow, against a WorkOS application of the CLI's own. What
14	 * comes back is a session: an access token that lasts an hour and a refresh
15	 * token that renews it, kept in the user's config directory, mode 600, and
16	 * renewed here without anyone noticing. Signing out forgets it.
17	 *
18	 * A machine with no browser and nobody at it, CI publishing a release, has
19	 * no way to confirm a code, so a key made on the profile page does instead:
20	 * `RUNLOG_API_KEY` in the environment, or `runlog login --key` pasted once.
21	 * Either way, every command that talks to the API sends what it has as the
22	 * bearer and the API tells the two apart.
23	 *
24	 * `claim` proves a signing key is the account's: the API hands out a nonce,
25	 * this signs it with the private key, and the API records the fingerprint
26	 * under the account, from then on the app names the account beside that
27	 * signature. `publish` puts a pack in the account's library, the same call
28	 * sync makes. `sign` and `issue` ask the API whether the key is claimed
29	 * before they sign, and refuse if not. Signing is arithmetic and a fork of
30	 * this file can always do the arithmetic; what an account buys is the right
31	 * to be named when the pack is opened, and the refusal is what keeps a name
32	 * on a signature meaning something.
33	 */
34	
35	const DEFAULT_API = "https://runlog.scrthq.com/api";
36	
37	export interface Credentials {
38	  api: string;
39	  /** A key from the profile page: CI's way in, or `login --key`. */
40	  key?: string;
41	  /** A session from `runlog login`: the browser's way in, from a terminal. */
42	  session?: Session;
43	  savedAt: string;
44	}
45	
46	/** The CLI's own config directory: `RUNLOG_CONFIG_DIR`, else the platform's rule, for `runlog`. */
47	function configDir(): string {
48	  return process.env["RUNLOG_CONFIG_DIR"] ?? sessionConfigDir("runlog");
49	}
50	
51	const credentialsPath = () => join(configDir(), "credentials.json");
52	
53	/** What is saved, or what the environment says: RUNLOG_API_KEY wins, for CI. */
54	export function credentials(): Credentials | null {
55	  const fromEnv = process.env["RUNLOG_API_KEY"];
56	  if (fromEnv) return { api: process.env["RUNLOG_API"] ?? DEFAULT_API, key: fromEnv, savedAt: "" };
57	  try {
58	    const raw = JSON.parse(readFileSync(credentialsPath(), "utf8")) as Partial<Credentials>;
59	    if (typeof raw.api !== "string") return null;
60	    if (typeof raw.key === "string") return { api: raw.api, key: raw.key, savedAt: raw.savedAt ?? "" };
61	    const s = raw.session;
62	    if (s && typeof s.accessToken === "string" && typeof s.refreshToken === "string" && typeof s.clientId === "string") {
63	      return {
64	        api: raw.api,
65	        session: {
66	          clientId: s.clientId,
67	          issuer: s.issuer ?? WORKOS,
68	          accessToken: s.accessToken,
69	          refreshToken: s.refreshToken,
70	          expiresAt: s.expiresAt ?? "",
71	        },
72	        savedAt: raw.savedAt ?? "",
73	      };
74	    }
75	    return null;
76	  } catch {
77	    return null;
78	  }
79	}
80	
81	function save(creds: Credentials): void {
82	  const dir = configDir();
83	  mkdirSync(dir, { recursive: true });
84	  writeFileSync(credentialsPath(), `${JSON.stringify(creds, null, 2)}\n`, "utf8");
85	  try {
86	    chmodSync(credentialsPath(), 0o600);
87	  } catch {
88	    /* Windows */
89	  }
90	}
91	
92	async function ask(prompt: string, hidden = false): Promise<string> {
93	  const rl = createInterface({ input: process.stdin, output: process.stdout, terminal: true });
94	  return new Promise((done) => {
95	    if (hidden) {
96	      // Echo nothing: the key is a secret, and a terminal scrollback is a log.
97	      const out = process.stdout as NodeJS.WriteStream & { muted?: boolean };
98	      process.stdout.write(prompt);
99	      const original = out.write.bind(out);
100	      out.write = ((chunk: unknown, ...rest: unknown[]) => {
101	        if (typeof chunk === "string" && chunk !== "\n" && chunk !== "\r\n") return true;
102	        return (original as (...a: unknown[]) => boolean)(chunk, ...rest);
103	      }) as typeof out.write;
104	      rl.question("", (answer) => {
105	        out.write = original as typeof out.write;
106	        process.stdout.write("\n");
107	        rl.close();
108	        done(answer.trim());
109	      });
110	    } else {
111	      rl.question(prompt, (answer) => {
112	        rl.close();
113	        done(answer.trim());
114	      });
115	    }
116	  });
117	}
118	
119	const WORKOS = "https://api.workos.com";
120	
121	/* ---- the API, as whoever is signed in ---------------------------------------- */
122	
123	/**
124	 * The bearer to send: the key, or the session's access token, renewed first
125	 * when it is about to lapse. `force` renews regardless, after a 401.
126	 */
127	export async function bearer(creds: Credentials, force = false, deps: FlowDeps = realDeps): Promise<string> {
128	  if (creds.key) return creds.key;
129	  if (!creds.session) throw new Error("not signed in: run `runlog login`");
130	  const lapsing = !creds.session.expiresAt || needsRenewal(creds.session, deps.now());
131	  if (!force && !lapsing) return creds.session.accessToken;
132	  const session = await renew(creds.session, deps);
133	  creds.session = session;
134	  if (!process.env["RUNLOG_API_KEY"]) save(creds);
135	  return session.accessToken;
136	}
137	
138	/** One call to the API as whoever is signed in. Throws with the API's own words on a failure. */
139	export async function api<T>(method: string, path: string, body?: unknown): Promise<T> {
140	  const creds = credentials();
141	  if (!creds) throw new Error("not signed in: run `runlog login`");
142	  const once = async (token: string) => {
143	    const response = await fetch(`${creds.api.replace(/\/$/, "")}${path}`, {
144	      method,
145	      headers: { authorization: `Bearer ${token}`, ...(body !== undefined ? { "content-type": "application/json" } : {}) },
146	      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
147	    });
148	    const text = await response.text();
149	    let parsed: unknown = null;
150	    try {
151	      parsed = JSON.parse(text);
152	    } catch {
153	      throw new Error(`the API at ${creds.api} did not answer as expected (${response.status})`);
154	    }
155	    return { status: response.status, parsed };
156	  };
157	  let answer = await once(await bearer(creds));
158	  // A session's token can be refused between the expiry check and the call;
159	  // renew once and try again before deciding the sign-in is gone.
160	  if (answer.status === 401 && creds.session) answer = await once(await bearer(creds, true));
161	  if (answer.status === 401) {
162	    throw new Error(
163	      creds.key
164	        ? "that key is not accepted; make a new one on your profile page and `runlog login --key` again"
165	        : "your sign-in has lapsed; run `runlog login` again",
166	    );
167	  }
168	  if (answer.status >= 400) {
169	    const said = (answer.parsed as { error?: string } | null)?.error;
170	    throw new Error(said ?? `the API said ${answer.status}`);
171	  }
172	  return answer.parsed as T;
173	}
174	
175	/* ---- commands ---------------------------------------------------------------- */
176	
177	async function greet(apiUrl: string): Promise<void> {
178	  const me = await api<{ profile?: { name?: string; email?: string } }>("GET", "/me");
179	  const who = me.profile?.name ?? me.profile?.email ?? "you";
180	  console.log(`signed in as ${who} at ${apiUrl}`);
181	}
182	
183	export async function cmdLogin(args: string[], deps: FlowDeps = realDeps): Promise<number> {
184	  const apiUrl = (flag(args, "--api") ?? process.env["RUNLOG_API"] ?? DEFAULT_API).replace(/\/$/, "");
185	  if (process.env["RUNLOG_API_KEY"]) {
186	    console.error("RUNLOG_API_KEY is set, so that is what every command will use; unset it to sign in as yourself");
187	    return 1;
188	  }
189	
190	  if (args.includes("--key")) {
191	    console.log("Paste a command-line key from your profile page in Runlog. It is not shown as you type.");
192	    const key = await ask("key: ", true);
193	    if (!key.startsWith("rl_")) {
194	      console.error("that does not look like a Runlog key; they begin with rl_");
195	      return 1;
196	    }
197	    // Prove it before keeping it, so a typo is caught here and not on the next command.
198	    save({ api: apiUrl, key, savedAt: new Date().toISOString() });
199	    try {
200	      await greet(apiUrl);
201	      return 0;
202	    } catch (error) {
203	      unlinkSync(credentialsPath());
204	      console.error(error instanceof Error ? error.message : String(error));
205	      return 1;
206	    }
207	  }
208	
209	  try {
210	    // Which WorkOS application to sign in against is the API's to say.
211	    const response = await deps.fetch(`${apiUrl}/auth/cli`, { headers: { accept: "application/json" } });
212	    const text = await response.text();
213	    let about: { clientId?: string | null; issuer?: string } = {};
214	    try {
215	      about = JSON.parse(text) as typeof about;
216	    } catch {
217	      throw new Error(`the API at ${apiUrl} did not answer as expected (${response.status})`);
218	    }
219	    if (!about.clientId)
220	      throw new Error(`the API at ${apiUrl} cannot sign in a terminal yet; use \`runlog login --key\` with a key from your profile page`);
221	    const session = await deviceFlow(about.clientId, about.issuer ?? WORKOS, deps);
222	    save({ api: apiUrl, session, savedAt: new Date().toISOString() });
223	    await greet(apiUrl);
224	    return 0;
225	  } catch (error) {
226	    console.error(error instanceof Error ? error.message : String(error));
227	    return 1;
228	  }
229	}
230	
231	export function cmdLogout(): number {
232	  const creds = credentials();
233	  if (existsSync(credentialsPath())) {
234	    unlinkSync(credentialsPath());
235	    console.log(creds?.key ? "signed out; the key is still valid until you revoke it on your profile page" : "signed out");
236	  } else {
237	    console.log("not signed in");
238	  }
239	  return 0;
240	}
241	
242	export async function cmdWhoami(): Promise<number> {
243	  try {
244	    const creds = credentials();
245	    const me = await api<{ sub: string; scope?: string; profile?: { name?: string; email?: string } }>("GET", "/me");
246	    const claims = await api<{ claims: Array<{ fingerprint: string }> }>("GET", "/claims");
247	    const how = process.env["RUNLOG_API_KEY"]
248	      ? "with RUNLOG_API_KEY"
249	      : creds?.key
250	        ? "with a key from the profile page"
251	        : "from the browser";
252	    console.log(`${me.profile?.name ?? "(no name)"} <${me.profile?.email ?? "?"}>  ${me.sub}`);
253	    console.log(`signed in ${how} at ${creds?.api ?? DEFAULT_API}${me.scope === "release" ? " (a key that only releases)" : ""}`);
254	    console.log(
255	      claims.claims.length > 0
256	        ? `claimed signing keys: ${claims.claims.map((c) => c.fingerprint).join(", ")}`
257	        : "no claimed signing keys yet: `runlog claim key.json`",
258	    );
259	    return 0;
260	  } catch (error) {
261	    console.error(error instanceof Error ? error.message : String(error));
262	    return 1;
263	  }
264	}
265	
266	interface StoredKey {
267	  publicKey: string;
268	  privateKey: string;
269	  fingerprint: string;
270	}
271	
272	function readKey(path: string): StoredKey {
273	  const key = JSON.parse(readFileSync(resolve(path), "utf8")) as Partial<StoredKey>;
274	  if (!key.privateKey || !key.publicKey) throw new Error(`${path} is not a runlog signing key`);
275	  return { publicKey: key.publicKey, privateKey: key.privateKey, fingerprint: key.fingerprint ?? "" };
276	}
277	
278	export async function cmdClaim(args: string[]): Promise<number> {
279	  const keyPath = args.filter((a) => !a.startsWith("-"))[0];
280	  if (!keyPath) {
281	    console.error("usage: runlog claim key.json");
282	    return 2;
283	  }
284	  try {
285	    const key = readKey(keyPath);
286	    const { nonce } = await api<{ nonce: string }>("POST", "/claims/nonce");
287	    const signature = await signBytes(new TextEncoder().encode(nonce), key.privateKey);
288	    const { claim } = await api<{ claim: { fingerprint: string; name: string | null } }>("POST", "/claims", {
289	      publicKey: key.publicKey,
290	      nonce,
291	      signature,
292	    });
293	    console.log(`claimed ${claim.fingerprint}${claim.name ? ` as ${claim.name}` : ""}`);
294	    console.log("packs signed with this key now show your name in the app");
295	    return 0;
296	  } catch (error) {
297	    console.error(error instanceof Error ? error.message : String(error));
298	    return 1;
299	  }
300	}
301	
302	/**
303	 * Is this key claimed by the signed-in account? `sign` and `issue` refuse
304	 * otherwise, with the command that fixes it.
305	 */
306	export async function requireClaimed(publicKey: string): Promise<void> {
307	  const fp = await fingerprint(publicKey);
308	  const { claims } = await api<{ claims: Array<{ fingerprint: string }> }>("GET", "/claims");
309	  if (!claims.some((c) => c.fingerprint === fp)) {
310	    throw new Error(`this key (${fp}) is not claimed by your account: run \`runlog claim key.json\` first, so the app can name you`);
311	  }
312	}
313	
314	export async function cmdPublish(args: string[]): Promise<number> {
315	  const input = args.filter((a) => !a.startsWith("-"))[0];
316	  if (!input) {
317	    console.error("usage: runlog upload <pack.yaml|pack.json>");
318	    return 2;
319	  }
320	  try {
321	    const path = resolve(input);
322	    const text = readFileSync(path, "utf8");
323	    const format = detectFormat(path);
324	    const doc = (format === "json" ? JSON.parse(text) : YAML.parse(text)) as Record<string, unknown>;
325	    const id = String(doc["id"] ?? "");
326	    if (!id) throw new Error("the pack has no id");
327	    const { createHash } = await import("node:crypto");
328	    const hash = createHash("sha256").update(text).digest("hex").slice(0, 16);
329	    const at = new Date().toISOString();
330	    await api("PUT", `/packs/${encodeURIComponent(id)}`, {
331	      title: String(doc["title"] ?? id),
332	      version: String(doc["version"] ?? ""),
333	      format,
334	      filename: input.split(/[\\/]/).pop(),
335	      importedAt: at,
336	      updatedAt: at,
337	      hash,
338	      source: text,
339	    });
340	    console.log(`uploaded ${id} to your own library, where only you can see it; it reaches your devices on their next sync`);
341	    return 0;
342	  } catch (error) {
343	    console.error(error instanceof Error ? error.message : String(error));
344	    return 1;
345	  }
346	}
347	
348	function flag(args: string[], name: string): string | undefined {
349	  const at = args.indexOf(name);
350	  return at === -1 ? undefined : args[at + 1];
351	}
352	
353	/**
354	 * The price a release is listed at: `--price 3.00` in dollars, `--free`, or
355	 * neither, which keeps whatever the marketplace has. The API takes whole cents.
356	 */
357	export function priceFlag(args: string[]): { amount: number; currency: "usd" } | "free" | "keep" | { error: string } {
358	  if (args.includes("--free")) return "free";
359	  const raw = flag(args, "--price");
360	  if (raw === undefined) return "keep";
361	  const m = /^\$?(\d+)(?:\.(\d{1,2}))?$/.exec(raw.trim());
362	  if (!m) return { error: `--price wants dollars and cents, like 3.00; got ${JSON.stringify(raw)}` };
363	  const cents = Number(m[1]) * 100 + Number((m[2] ?? "0").padEnd(2, "0"));
364	  if (cents < 100 || cents > 100_000) return { error: "--price is from 1.00 to 1000.00" };
365	  return { amount: cents, currency: "usd" };
366	}
367	
368	/**
369	 * A release to the marketplace: the signed pack goes up as the publisher's
370	 * master and is listed, at a price, free, or as it already is. This is what
371	 * a build server runs when a tag is pushed, with RUNLOG_API_KEY set; the
372	 * marketplace seals what you signed and never sees your signing key.
373	 */
374	export async function cmdRelease(args: string[]): Promise<number> {
375	  const input = args.filter((a) => !a.startsWith("-"))[0];
376	  const price = priceFlag(args);
377	  if (!input || (typeof price === "object" && "error" in price)) {
378	    if (typeof price === "object" && "error" in price) console.error(price.error);
379	    console.error("usage: runlog release <pack.yaml|pack.json> [--price 3.00 | --free] [--draft]");
380	    return 2;
381	  }
382	  try {
383	    const path = resolve(input);
384	    const text = readFileSync(path, "utf8");
385	    const format = detectFormat(path);
386	    const raw = (format === "json" ? JSON.parse(text) : YAML.parse(text)) as Record<string, unknown>;
387	    const verified = await verifyPack(raw);
388	    if (verified.status === "unsigned")
389	      throw new Error("the pack is not signed; run `runlog sign` first, since the marketplace seals what you signed");
390	    if (verified.status === "invalid") throw new Error(`the signature does not match the pack (${verified.reason}); sign it again`);
391	    const listing = listingPayload(text, format, raw);
392	    if (!listing.ok) throw new Error(listing.error);
393	    const { pack, payload } = listing;
